import {
  ValidationWorkspaceApiError,
  type ValidationWorkspaceDocumentDto,
} from "./types";

export type ValidationWorkspaceRuntimeProfile = "local" | "aws";

export interface ValidationWorkspaceRuntimeConfig {
  profile: ValidationWorkspaceRuntimeProfile;
  apiBaseUrl: string;
}

const LOCAL_DEFAULT_API_BASE_URL = "http://localhost:8000";

export function resolveValidationWorkspaceRuntime(): ValidationWorkspaceRuntimeConfig {
  const rawProfile = process.env.NEXT_PUBLIC_RUNTIME_PROFILE;
  const profile: ValidationWorkspaceRuntimeProfile =
    rawProfile === "aws" ? "aws" : "local";

  const apiBaseUrl =
    process.env.NEXT_PUBLIC_API_BASE_URL?.replace(/\/+$/, "") ||
    LOCAL_DEFAULT_API_BASE_URL;

  return { profile, apiBaseUrl };
}

export function buildValidationWorkspaceUrl(documentId: string): string {
  const { apiBaseUrl } = resolveValidationWorkspaceRuntime();
  return `${apiBaseUrl}/documents/${encodeURIComponent(documentId)}`;
}

async function readRemoteErrorMessage(response: Response): Promise<string | null> {
  try {
    const contentType = response.headers?.get?.("content-type") ?? "";

    if (contentType.includes("application/json")) {
      const payload = (await response.json()) as {
        message?: string;
        error?: string;
        detail?: string;
      };

      return payload.message ?? payload.error ?? payload.detail ?? null;
    }

    const text = await response.text();
    return text.trim().length > 0 ? text.trim() : null;
  } catch {
    return null;
  }
}

export async function fetchValidationWorkspaceDocument(
  documentId: string,
): Promise<ValidationWorkspaceDocumentDto> {
  const response = await fetch(buildValidationWorkspaceUrl(documentId), {
    method: "GET",
    headers: {
      Accept: "application/json",
    },
    cache: "no-store",
    credentials: "include",
  });

  if (response.ok) {
    return (await response.json()) as ValidationWorkspaceDocumentDto;
  }

  const remoteMessage =
    (await readRemoteErrorMessage(response)) ??
    "Impossibile caricare il dettaglio del documento.";

  if (response.status === 401) {
    throw new ValidationWorkspaceApiError(
      "UNAUTHORIZED",
      401,
      "Sessione non valida o scaduta.",
    );
  }

  if (response.status === 403) {
    throw new ValidationWorkspaceApiError(
      "FORBIDDEN",
      403,
      "Non sei autorizzato a visualizzare questo documento.",
    );
  }

  if (response.status === 404) {
    throw new ValidationWorkspaceApiError(
      "NOT_FOUND",
      404,
      "Documento non trovato.",
    );
  }

  throw new ValidationWorkspaceApiError("REMOTE_ERROR", response.status, remoteMessage);
}
