"use client";

import { useEffect } from "react";
import { useQuery } from "@tanstack/react-query";

import { fetchValidationWorkspaceDocument } from "./runtime";
import {
  getMissingRequiredFieldIds,
  useValidationWorkspaceStore,
} from "./store";
import type { ValidationWorkspaceDocumentDto } from "./types";

export interface UseValidationWorkspaceOptions {
  documentId: string;
  initialDocument?: ValidationWorkspaceDocumentDto;
}

export function useValidationWorkspace({
  documentId,
  initialDocument,
}: UseValidationWorkspaceOptions) {
  const hydrate = useValidationWorkspaceStore((state) => state.hydrate);
  const rawValues = useValidationWorkspaceStore((state) => state.values);
  const hydratedDocumentId = useValidationWorkspaceStore(
    (state) => state.hydratedDocumentId,
  );
  const setFieldValue = useValidationWorkspaceStore((state) => state.setFieldValue);
  const reset = useValidationWorkspaceStore((state) => state.reset);

  const query = useQuery({
    queryKey: ["validation-workspace", documentId],
    queryFn: () => fetchValidationWorkspaceDocument(documentId),
    enabled: initialDocument === undefined,
    initialData: initialDocument,
    staleTime: 15_000,
    retry: false,
    refetchOnWindowFocus: false,
  });

  useEffect(() => {
    if (query.data) {
      hydrate(query.data);
    }
  }, [hydrate, query.data]);

  useEffect(() => () => reset(), [reset]);

  const values = hydratedDocumentId === documentId ? rawValues : {};

  return {
    ...query,
    values,
    setFieldValue,
    missingRequiredFieldIds: query.data
      ? getMissingRequiredFieldIds(query.data, values)
      : [],
  };
}
