function formatDateTime(value: string | null): string {
  if (!value) {
    return "N/D";
  }

  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    return "N/D";
  }

  return new Intl.DateTimeFormat("it-IT", {
    dateStyle: "short",
    timeStyle: "short",
  }).format(date);
}

function formatConfidence(value: number | null): string {
  if (value === null) {
    return "N/D";
  }

  const percent = value <= 1 ? Math.round(value * 100) : Math.round(value);
  return `${percent}%`;
}

function formatProvenance(provenance: ValidationFieldProvenanceDto | null): string {
  if (!provenance) {
    return "Non disponibile";
  }

  const parts: string[] = [];

  if (provenance.source) {
    parts.push(provenance.source);
  }

  if (provenance.page !== null && provenance.page !== undefined) {
    parts.push(`pag. ${provenance.page}`);
  }

  if (provenance.snippet) {
    parts.push(`snippet: ${provenance.snippet}`);
  }

  return parts.length > 0 ? parts.join(" • ") : "Non disponibile";
}

function getReadOnlyActionHint(status: DocumentWorkflowStatus): string {
