                <dd className="inline">{formatDateTime(document.createdAt)}</dd>
              </div>
              <div>
                <dt className="inline font-semibold">Aggiornato:</dt>{" "}
                <dd className="inline">{formatDateTime(document.updatedAt)}</dd>
              </div>
            </dl>
          </div>
        </div>
      </header>

      {document.status === "eccezione" ? (
        <section
          role="alert"
          className="flex flex-col gap-4 rounded-2xl border border-rose-200 bg-rose-50 p-5 shadow-sm lg:flex-row lg:items-center lg:justify-between"
        >
          <div className="flex items-start gap-3">
            <AlertTriangle className="mt-0.5 h-5 w-5 text-rose-700" aria-hidden="true" />
