                <h2 className="text-lg font-semibold text-slate-950">
                  Azioni operatore
                </h2>
                <p className="text-sm text-slate-600">
                  Il completamento della validazione resta human-in-the-loop.
                </p>
              </div>

              {canAttemptValidation ? (
                <button
                  type="button"
                  disabled={!canCompleteValidation}
                  className={[
                    "inline-flex items-center justify-center rounded-lg px-4 py-2 text-sm font-semibold shadow-sm transition",
                    canCompleteValidation
                      ? "bg-sky-700 text-white hover:bg-sky-800"
                      : "cursor-not-allowed bg-slate-200 text-slate-500",
