              ) : (
                <span className="inline-flex items-center gap-2 rounded-lg bg-slate-100 px-4 py-2 text-sm font-medium text-slate-600">
                  <ShieldAlert className="h-4 w-4" aria-hidden="true" />
                  Nessuna validazione disponibile in questo stato
                </span>
              )}
            </div>

            {canAttemptValidation && missingRequiredFieldIds.length > 0 ? (
              <p className="mt-3 text-sm text-amber-800">
                Completa i campi obbligatori evidenziati prima di procedere.
