            ) : null}

            {!canAttemptValidation ? (
              <p className="mt-3 text-sm text-slate-600">
                {getReadOnlyActionHint(document.status)}
              </p>
            ) : null}
          </section>
        </section>
      </div>
    </div>
  );
}

export interface ValidationWorkspaceScreenProps {
  documentId: string;
  initialDocument?: ValidationWorkspaceDocumentDto;
  onRetry?: (documentId: string) => void | Promise<void>;
  onValidate?: (payload: {
    documentId: string;
    values: Record<string, string>;
  }) => void | Promise<void>;
}

export function ValidationWorkspaceScreen({
  documentId,
  initialDocument,
  onRetry,
  onValidate,
}: ValidationWorkspaceScreenProps) {
  const {
    data,
    error,
    isLoading,
    values,
    setFieldValue,
    missingRequiredFieldIds,
  } = useValidationWorkspace({
    documentId,
    initialDocument,
  });

  if (error instanceof ValidationWorkspaceApiError) {
    if (error.code === "UNAUTHORIZED") {
      return (
        <ErrorStateCard
          title="Accesso richiesto"
          message={error.message}
          actionHref="/login"
          actionLabel="Vai al login"
        />
      );
    }

    if (error.code === "FORBIDDEN") {
      return (
        <ErrorStateCard
          title="Accesso non autorizzato"
          message={error.message}
          actionHref="/unauthorized"
          actionLabel="Vai alla pagina autorizzazioni"
        />
      );
    }

    if (error.code === "NOT_FOUND") {
      return <ErrorStateCard title="Documento non trovato" message={error.message} />;
    }

    return (
      <ErrorStateCard
        title="Errore nel caricamento del documento"
        message={error.message}
      />
    );
  }

  if (isLoading) {
    return (
      <div className="mx-auto max-w-5xl px-6 py-10">
        <div className="rounded-2xl border border-slate-200 bg-white p-6 text-sm text-slate-600 shadow-sm">
          Caricamento workspace di validazione…
        </div>
      </div>
    );
  }

  if (!data) {
    return (
      <ErrorStateCard
        title="Documento non disponibile"
        message="Il dettaglio del documento non è disponibile in questo momento."
      />
    );
  }

  return (
    <ValidationWorkspaceView
      document={data}
      values={values}
      missingRequiredFieldIds={missingRequiredFieldIds}
      onFieldChange={setFieldValue}
      onRetry={onRetry}
      onValidate={onValidate}
    />
  );
